 package org.lpgtug.farmacias.models;
 
 import java.text.SimpleDateFormat;
 import java.util.Date;
 
 import com.j256.ormlite.field.DatabaseField;
 import com.j256.ormlite.table.DatabaseTable;
 
 /**
  * A simple demonstration object we are creating and persisting to the database.
  */
 @DatabaseTable(tableName = "turno")
 public class Turno {
 	public static final String fechaDesde = "inicio"; 
 	public static final String fechaFin = "fin"; 
 	// id is generated by the database and set on the object automagically
	@DatabaseField(generatedId = true)
 	Integer id;
 	@DatabaseField(index = true, columnName = fechaDesde)
 	public Date inicio;
 	@DatabaseField(columnName = fechaFin)
 	public Date fin;
 	@DatabaseField (canBeNull = false, foreign = true)
 	Farmacia farmacia;
 
 	Turno() {
 		// needed by ormlite
 	}
 	public int getId() {
 		return id;
 	}
 
 	public void setId(int id) {
 		this.id = id;
 	}
 
 	public Date getInicio() {
 		return inicio;
 	}
 
 	public void setInicio(Date inicio) {
 		this.inicio = inicio;
 	}
 
 	public Date getFin() {
 		return fin;
 	}
 
 	public void setFin(Date fin) {
 		this.fin = fin;
 	}
 
 	public Farmacia getFarmacia() {
 		return farmacia;
 	}
 
 	public void setFarmacia(Farmacia farmacia) {
 		this.farmacia = farmacia;
 	}
 
 	public Turno(Farmacia farmacia) {
 		this.inicio = new Date();
 		this.fin = new Date();
 		this.farmacia = farmacia;
 	}
	public Turno(Date desde, Date hasta, Farmacia farmacia){
 		this.inicio = desde;
 		this.fin = hasta;
 		this.farmacia = farmacia;
 	}
 	
 
 	@Override
 	public String toString() {
 		StringBuilder sb = new StringBuilder();
 		sb.append("id=").append(id);
 		sb.append(", ").append("inicio=").append(inicio);
 		sb.append(", ").append("fin=").append(fin);
 		//SimpleDateFormat dateFormatter = new SimpleDateFormat("MM/dd/yyyy HH:mm:ss.S");
 		sb.append(", ").append("farmacia=").append(farmacia);
 		return sb.toString();
 	}
 }
